// Copies the ClearingHouse ABI from the Foundry build into core/abi.ts so the app and scripts share one typed copy.
// Run after `forge build` in contracts/: `node scripts/export-abi.ts`
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
const artifact = JSON.parse(readFileSync(`${root}contracts/out/ClearingHouse.sol/ClearingHouse.json`, "utf8"));
const out =
  "// Generated by scripts/export-abi.ts from contracts/out. Do not edit by hand.\n" +
  `export const clearingHouseAbi = ${JSON.stringify(artifact.abi, null, 2)} as const;\n`;
writeFileSync(`${root}core/abi.ts`, out);
console.log(`core/abi.ts: ${artifact.abi.length} entries`);
